sys_script_include.script:
var BranchUtils = Class.create();
BranchUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkManagerExists: function() {
        var managerSysId = this.getParameter('sysparm_manager');
        var currentSysId = this.getParameter('sysparm_current');

        if (!managerSysId) {
            return false;
        }

        var branchGR = new GlideRecord('x_1836478_cloud_0_branch');
        branchGR.addQuery('branch_manager', managerSysId);

        // Ignorando o registro atual
        if (currentSysId) {
            branchGR.addQuery('sys_id', '!=', currentSysId);
        }

        branchGR.query();

        return branchGR.hasNext().toString();
    },

    checkDuplicateName: function() {
        var name = this.getParameter('sysparm_branch_name');
        var currentSysId = this.getParameter('sysparm_current');

        if (!name) {
            return false;
        }

        var gr = new GlideRecord('x_1836478_cloud_0_branch');
        gr.addQuery('name', name);
        if (currentSysId) {
            gr.addQuery('sys_id', '!=', currentSysId);
        }
        gr.query();

        return gr.hasNext().toString();
    },

    checkDuplicateLocation: function() {
        var city = this.getParameter('sysparm_city');
        var state = this.getParameter('sysparm_state');
        var currentSysId = this.getParameter('sysparm_current');

        if (!city || !state) {
            return false;
        }

        var gr = new GlideRecord('x_1836478_cloud_0_branch');
        gr.addQuery('city', city);
        gr.addQuery('state', state);
        if (currentSysId) {
            gr.addQuery('sys_id', '!=', currentSysId);
        }
        gr.query();

        return gr.hasNext().toString();
    },

    type: 'BranchUtils'
});
